#define MAX 25
int isPrimeArr[MAX+1];
void sieve() {
    for (int i = 0; i <= MAX; i++) isPrimeArr[i] = 1;
    isPrimeArr[0] = isPrimeArr[1] = 0;
    for (int x = 2; x <= MAX; x++) {
        if (isPrimeArr[x]) {
            for (int i = 2; i * x <= MAX; i++) {
                isPrimeArr[i * x] = 0;
            }
        }
    }
}

