    printf("sizeof(a) in main = %zu\n", sizeof(a));
    printf("address of a in main = %p\n", a);
    int m = max(a, 5);
    printf("max = %d\n", m);
    printf("a[0] after max = %d\n", a[0]);
    int *p = &m;
    printf("*p = %d, p[0] = %d\n", *p, p[0]);
    printf("*a = %d\n", *a);
    return 0;
}

int sum(const int arr[], int n) {
    int total = 0;
    for (int i = 0; i < n; i++) {
        total += arr[i];
    }
    return total;
}

