#include <stdio.h>
#include <stdlib.h>

int main() {
    int number;
    scanf("%d", &number);
    int *a = (int*)malloc(number * sizeof(int));
    if (a == NULL) {
        printf("内存分配失败\n");
        return 1;
    }
    for (int i = 0; i < number; i++) {
        scanf("%d", &a[i]);
    }
    for (int i = number - 1; i >= 0; i--) {
        printf("%d ", a[i]);
    }
    printf("\n");
    free(a);
    return 0;
}

