int mylen(const char *s) {
    int idx = 0;
    while (s[idx] != '\0') {
        idx++;
    }
    return idx;
}

int mycmp(const char *s1, const char *s2) {
    while (*s1 == *s2 && *s1 != '\0') {
        s1++;
        s2++;
    }
    return *s1 - *s2;
}

char *my_strcpy(char *dst, const char *src) {
    char *ret = dst;
    while (*src != '\0') {
        *dst = *src;
        dst++;
        src++;
    }
    *dst = '\0';
    return ret;
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main() {
    char s[] = "hello";
    char *p = strchr(s, 'l');
    printf("%s\n", p); // llo

    // 找第二个l
    p = strchr(p + 1, 'l');
    printf("%s\n", p); // lo

    // 复制后半段
    char *t = (char*)malloc(strlen(p) + 1);
    strcpy(t, p);
    printf("%s\n", t); // lo
    free(t);

    // 截取前半段
    p = strchr(s, 'l');
    char c = *p;
    *p = '\0';
    t = (char*)malloc(strlen(s) + 1);
    strcpy(t, s);
    printf("%s\n", t); // he
    *p = c; // 恢复
    free(t);

    return 0;
}

